                    foreach (var prop0 in prop.Value.EnumerateObject())
                    {
                        if (prop0.Value.ValueKind == JsonValueKind.Null)
                        {
                            dictionary.Add(prop0.Name, null);
                        }
                        else
                        {
                            dictionary.Add(prop0.Name, BinaryData.FromString(prop0.Value.GetRawText()));
                        }
                    }
                    tags = dictionary;
                    continue;
                }
                if (prop.NameEquals("updatedTimestamp"u8))
                {
                    updatedTimestamp = prop.Value.GetString();
                    continue;
                }
                if (prop.NameEquals("provisioningState"u8))
                {
                    if (prop.Value.ValueKind == JsonValueKind.Null)
                    {
                        continue;
                    }
                    provisioningState = new ProvisioningState(prop.Value.GetString());
                    continue;
                }
                if (prop.NameEquals("arcDiscovery"u8))
                {
                    if (prop.Value.ValueKind == JsonValueKind.Null)
                    {
                        continue;
                    }
                    arcDiscovery = ArcDiscovery.DeserializeArcDiscovery(prop.Value, options);
                    continue;
                }
                if (prop.NameEquals("discoverySource"u8))
                {
                    if (prop.Value.ValueKind == JsonValueKind.Null)
                    {
                        continue;
                    }
                    discoverySource = new DiscoverySource(prop.Value.GetString());
                    continue;
                }
                if (prop.NameEquals("hypervisor"u8))
                {
                    hypervisor = prop.Value.GetString();
                    continue;
                }
                if (options.Format != "W")
                {
                    additionalBinaryDataProperties.Add(prop.Name, BinaryData.FromString(prop.Value.GetRawText()));
                }
            }
            return new ServerProperties(
                displayName,
                fqdn,
                networkAdapters ?? new ChangeTrackingList<ServerNetworkAdapter>(),
                hydratedFqdn,
                disks ?? new ChangeTrackingList<ServerDisk>(),
                validationRequired,
                processorInfo,
                firmware,
                secureBootEnabled,
                guestOSDetails,
                numberOfApplications,
                numberOfSoftware,
                numberOfSecurityRisks,
                guestDetailsDiscoveryTimestamp,
                isGuestDetailsDiscoveryInProgress,
                dependencyMapping,
                dependencyMappingStartOn,
                dependencyMappingEndTime,
                runAsAccountId,
                applianceNames ?? new ChangeTrackingList<string>(),
                errors ?? new ChangeTrackingList<HealthErrorDetails>(),
                applicationDiscovery,
                dependencyMapDiscovery,
                staticDiscovery,
                sqlDiscovery,
                webAppDiscovery,
                oracleDiscovery,
                springBootDiscovery,
                iisDiscovery,
                tomcatDiscovery,
                appsAndRoles,
                productSupportStatus,
                numberOfProcessorCore,
                allocatedMemoryInMb,
                operatingSystemDetails,
                biosSerialNumber,
                biosGuid,
                isDeleted,
                createdTimestamp,
                tags ?? new ChangeTrackingDictionary<string, BinaryData>(),
                updatedTimestamp,
                provisioningState,
                arcDiscovery,
                discoverySource,
                hypervisor,
                additionalBinaryDataProperties);
        }
    }
